    # Check the schedule for a cycle of rest hours
    for i in range(2 * n):
        if schedule[i % n] == 1:
            current_rest += 1
        else:
            if current_rest > 0:
                if first_zero_index != -1:
                    max_rest = max(max_rest, current_rest + first_zero_index)
